return {rw01={id="rw01",baseId="rwnpc01",combatid={2,100021},name="王庚金",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL王庚金：赵叔专门让人吩咐，不让镖局的人来掺和此事。恐怕只有我们自己了。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：听说那姓周的要在客栈大摆宴席，真不知道是怎么想的还敢如此张扬，不过这也正是我们的机会。一同去客栈看看吧。NOR"}},{type="gaintab",args={"318001",2}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL王庚金：居然有这么多人前来，还带了如此多护卫，麻烦了。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL王庚金：事已至此，不如跟他走上一趟，去小院看看这官员的葫芦里卖的什么药。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL王庚金：我倒是想到去跟哪些人说这事了，码头新来的海商、中央广场的小贩、车行的木匠、还有镖局的管事，跟他们讲完，这事肯定能散出去。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL王庚金：此事肯定散出去了，希望少侠相信那官员的决定是对的，我心里还是有点不安。NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1804"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL王庚金：先听听官员要说些什么吧。NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",2}},{type="inroom",args={"any","hdroom0508"}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318001",6}},{type="equaltab",args={"318008",0}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="gaintab",args={"318008",1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"318001",7}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={6,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"318005",4}}}},autoResult4={{type="gaintab",args={"318001",9}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}},{type="doc",args={"YEL王庚金：此事肯定散出去了，希望少侠相信那官员的决定是对的，我心里还是有点不安。NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="outgame",args={"hdfb1804"}}},autoCondition5={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult5={{type="objectFollow",args={}}},autoCondition6={relation="and",conditions={{type="inroom",args={"any","hdroom1805"}},{type="equaltab",args={"318012",0}},{type="equaltab",args={"318008",1}}}},autoResult6={{type="showbutton",args={3,0}},{type="showbutton",args={6,1}},{type="gaintab",args={"318012",1}}}},rw02={id="rw02",baseId="rwnpc26",combatid={2,100021},name="府兵",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL府兵：我已观察你们多时，看样子你们也是为了这客栈的事而来。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL府兵：内部守卫森严，即使翻过墙去也难敌大量人手。官员已有计划，希望你们能去一趟。就在东内大街的小院中。NOR"}},{type="gaintab",args={"318001",6}},{type="objectFollow",args={}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318007",0}}}},autoResult1={{type="objectFollow",args={}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw03={id="rw03",baseId="rwnpc14",combatid={2,100021},name="护卫",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL漕工：文本。NOR"}}},caozuoName2="询问",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw04={id="rw04",baseId="rwnpc27",combatid={2,100021},name="官员",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL官员：二位应该也是为那粮商囤粮之事而来，在下是这附近新上任的主政官，也正是为平此次饥荒而来。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：据我调查所知，此事背后牵扯不小，据传有邪派和官府，富商豪族互相勾结，才致此祸，二位若有疑惑，但问无妨。NOR"}},{type="outobject",args={"rw02"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},caozuoName2="关于邪派",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL官员：此事是朝中所传，在下也不知真假。有人在朝中传言邪派要借此饥荒收买人心伺机作乱，也有人说是在乘机血祭，亦或者是从中谋财，可都无直接证据，在下心中怀疑是有心人从中煽动舆情，以此影响救灾。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：如今可以肯定此事定有人贯通多个势力，且涉及官、商、匪三者，还请少侠多加小心。NOR"}},{type="showbutton",args={2,0}},{type="outobject",args={"rw02"}}},caozuoName3="关于救灾",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL官员：救灾事宜我已在安排，上官也竭力相助。各地粮草正通过水路陆路前来，前数日应当有几批粮草从漕运抵达，到了这附近却都没了音讯。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：此次从州中来此匆忙，携带的粮食投入市中也只是杯水车薪，想要救灾还得另行计划。NOR"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},caozuoName4="救灾计划",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL官员：想要解决此次饥荒，需要有人继续抬高粮价，告知所有人此地粮价飞涨，让商人都愿意带粮食来，先解决掉粮食有无的问题，再做其他。NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="doc",args={"YEL王庚金：你这士人，粮价已经高到何种程度了还要抬价？少侠，这人就是想乘此机会囤粮高卖，再吸这百姓的血汗啊！NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：现在不是粮价高低之事，是有粮无粮之事！粮商手中囤粮，但多是本地粮商，基本都沆瀣一气，统一买卖。若能以高价诱外地粮食来此，补足市场辅以开仓放粮，才能真正解决此次饥荒。NOR"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},caozuoName5="协助造势",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL官员：多谢少侠，若能成功造势，将此地缺粮，粮价暴增之事传出，结合仓储中已有的储备，此次灾情必解。NOR"}},{type="gaintab",args={"318001",7}},{type="refresh",args={}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw05={id="rw05",baseId="rwnpc28",combatid={2,100021},name="海商",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL海商：这海上跑商虽是不易，但收入确实也高，再过两年就回镇上多置办几套房产田地，也是造福子孙了。NOR"}}},caozuoName2="宣扬消息",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL海商：少侠这话可当真？若是粮价还能再涨，我就是不走这趟货也要去外面多运些粮食过来，一来一回几倍的利，顶我走十趟货了。多谢少侠告知，某还有事，就先离开了。NOR"}},{type="addtab",args={"318005",1}},{type="refresh",args={}},{type="outobject",args={"rw05"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",8}}}},autoResult1={{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw06={id="rw06",baseId="rwnpc29",combatid={2,100021},name="木匠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL木匠：这木工活讲究一个巧字，要能用，又要实用，还得轻巧，这里面门道可不少。NOR"}}},caozuoName2="宣扬消息",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL木匠：唉，商人囤货居奇，低买高卖，就是苦了我们这些老百姓啊，少侠也多做准备吧。NOR"}},{type="addtab",args={"318005",1}},{type="refresh",args={}},{type="outobject",args={"rw06"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",8}}}},autoResult1={{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResul